#!/usr/bin/env node
// Regenerates vscode/src/dsc-version.ts from the repo-root DSC_VERSION file,
// the single source of truth for the pinned dsc release shared by all three
// editor clients. Wired into vscode's `compile` script so a bump to the root
// file flows into builds; scripts/check-dsc-version.sh fails CI if the
// generated file is committed out of step.

const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const version = fs.readFileSync(path.join(root, 'DSC_VERSION'), 'utf8').trim();
if (!/^\d+\.\d+\.\d+$/.test(version)) {
  console.error(`DSC_VERSION contains "${version}", expected semver`);
  process.exit(1);
}

const target = path.join(root, 'vscode', 'src', 'dsc-version.ts');
const contents =
  '// Generated by scripts/sync-dsc-version.js from the repo-root DSC_VERSION\n' +
  '// file. Do not edit by hand — the CI drift check (scripts/check-dsc-version.sh)\n' +
  `// fails the build if this value stops matching the root file.\n` +
  `export const DSC_VERSION = '${version}';\n`;

fs.writeFileSync(target, contents);
console.log(`synced vscode/src/dsc-version.ts to dsc v${version}`);
